sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ritm = steps('200').request_item;
  // (approve as ddi.approver — see happy-path step 6)
  var gr = new GlideRecord('sc_req_item');
  if (!gr.get(ritm)) { stepResult.setFailed('RITM not found'); return; }
  var notes = (gr.getValue('work_notes') || '').toLowerCase();
  var gateFailed = notes.indexOf('fail') > -1;
  var notClosed  = gr.getValue('state') != '3';           // 3 = Closed Complete
  if (gateFailed && notClosed) {
    stepResult.setOutputMessage('gate failed and request not closed — routed back as designed');
    stepResult.setSuccess();
  } else {
    stepResult.setFailed('expected gate fail + not-closed; got closed=' + (!notClosed) + ' gateFailed=' + gateFailed);
  }
})(outputs, steps, stepResult);
